#include "unity.h"
#include "mock_sh1106.h"
#include "mock_platform_io.h"
#include "display.h"
#include "config.h"
#include "logo.h"
#include "display_font.h"
#include <limits.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>

typedef struct
{
    unsigned int calls;
    uint8_t pages[32];
    unsigned int fail_at;
    bool enable_result;
    unsigned int enable_calls;
    char last_log[80];
} display_spy_t;

static display_spy_t spy;
static uint32_t fake_now_ms;
static sensors_snapshot_t readings;

static bool page_callback(sh1106_send_t send, uint8_t address, uint8_t page,
                          const uint8_t *pixels, int cmock_num_calls)
{
    (void)send;
    (void)address;
    (void)pixels;
    (void)cmock_num_calls;
    if (spy.calls < (unsigned int)(sizeof(spy.pages) / sizeof(spy.pages[0])))
    {
        spy.pages[spy.calls] = page;
    }
    spy.calls++;
    return (spy.fail_at == 0U) || (spy.calls != spy.fail_at);
}

static bool enable_callback(sh1106_send_t send, uint8_t address,
                            int cmock_num_calls)
{
    (void)send;
    (void)address;
    (void)cmock_num_calls;
    spy.enable_calls++;
    return spy.enable_result;
}

static uint32_t now_callback(int cmock_num_calls)
{
    (void)cmock_num_calls;
    return fake_now_ms;
}

static void log_callback(const char *message, int cmock_num_calls)
{
    (void)cmock_num_calls;
    if (message == NULL)
    {
        spy.last_log[0] = '\0';
        return;
    }
    (void)strncpy(spy.last_log, message, sizeof(spy.last_log) - 1U);
    spy.last_log[sizeof(spy.last_log) - 1U] = '\0';
}

static void enter_dashboard(void)
{
    /* A large elapsed timestamp completes stabilization without using its
       private duration constant. This also transfers the eight logo pages. */
    display_process(UINT32_MAX, &readings);
    TEST_ASSERT_TRUE(display_is_splash());

    /* Exercise the exact public splash-duration boundary. */
    display_process(fake_now_ms + LOGO_DISPLAY_MS, &readings);
    TEST_ASSERT_FALSE(display_is_splash());
}

void setUp(void)
{
    memset(&spy, 0, sizeof(spy));
    memset(&readings, 0, sizeof(readings));
    fake_now_ms = 100U;
    spy.enable_result = true;

    platform_io_init_IgnoreAndReturn(true);
    platform_io_read_IgnoreAndReturn(true);
    platform_io_write_IgnoreAndReturn(true);
    platform_io_transmit_IgnoreAndReturn(true);
    platform_io_dht_frame_IgnoreAndReturn(true);
    platform_io_telemetry_IgnoreAndReturn(true);
    platform_io_scan_Ignore();
    platform_io_led_Ignore();
    platform_io_poll_Ignore();
    platform_io_now_ms_StubWithCallback(now_callback);
    platform_io_log_StubWithCallback(log_callback);

    sh1106_init_IgnoreAndReturn(true);
    sh1106_page_StubWithCallback(page_callback);
    sh1106_enable_StubWithCallback(enable_callback);

    TEST_ASSERT_TRUE(display_init(0U));
    /* Exclude any initialization transfers from process-call observations. */
    memset(&spy, 0, sizeof(spy));
    spy.enable_result = true;
}

void tearDown(void)
{
}

void test_display_process_01(void)
{
    display_process(UINT32_MAX, NULL);

    TEST_ASSERT_EQUAL_INT(0, spy.calls);
    TEST_ASSERT_EQUAL_INT(0, spy.enable_calls);
}

void test_display_process_02(void)
{
    display_process(0U, &readings);

    TEST_ASSERT_EQUAL_INT(0, spy.calls);
    TEST_ASSERT_EQUAL_INT(0, spy.enable_calls);
}

void test_display_process_03(void)
{
    display_process(UINT32_MAX, &readings);

    TEST_ASSERT_EQUAL_INT(8, spy.calls);
    for (uint8_t page = 0U; page < 8U; page++)
    {
        TEST_ASSERT_EQUAL_INT(page, spy.pages[page]);
    }
    TEST_ASSERT_EQUAL_INT(1, spy.enable_calls);
    TEST_ASSERT_TRUE(display_is_splash());
    TEST_ASSERT_EQUAL_STRING("OLED logo transfer complete; splash started\r\n", spy.last_log);
}

void test_display_process_04(void)
{
    spy.fail_at = 3U;
    display_process(UINT32_MAX, &readings);

    TEST_ASSERT_EQUAL_INT(3, spy.calls);
    TEST_ASSERT_EQUAL_INT(0, spy.enable_calls);
    TEST_ASSERT_EQUAL_STRING("FAULT OLED logo write\r\n", spy.last_log);

    display_process(UINT32_MAX, &readings);
    TEST_ASSERT_EQUAL_INT(3, spy.calls);
}

void test_display_process_05(void)
{
    spy.enable_result = false;
    display_process(UINT32_MAX, &readings);

    TEST_ASSERT_EQUAL_INT(8, spy.calls);
    TEST_ASSERT_EQUAL_INT(1, spy.enable_calls);
    TEST_ASSERT_EQUAL_STRING("FAULT OLED enable\r\n", spy.last_log);

    display_process(UINT32_MAX, &readings);
    TEST_ASSERT_EQUAL_INT(8, spy.calls);
    TEST_ASSERT_EQUAL_INT(1, spy.enable_calls);
}

void test_display_process_06(void)
{
    display_process(UINT32_MAX, &readings);
    TEST_ASSERT_TRUE(display_is_splash());
    TEST_ASSERT_EQUAL_INT(8, spy.calls);

    display_process(fake_now_ms + LOGO_DISPLAY_MS - 1U, &readings);

    TEST_ASSERT_TRUE(display_is_splash());
    TEST_ASSERT_EQUAL_INT(8, spy.calls);
}

void test_display_process_07(void)
{
    display_process(UINT32_MAX, &readings);
    TEST_ASSERT_TRUE(display_is_splash());

    display_process(fake_now_ms + LOGO_DISPLAY_MS, &readings);

    TEST_ASSERT_FALSE(display_is_splash());
    TEST_ASSERT_EQUAL_INT(9, spy.calls);
    TEST_ASSERT_EQUAL_INT(0, spy.pages[8]);
    TEST_ASSERT_EQUAL_STRING("OLED dashboard transition\r\n", spy.last_log);
}

void test_display_process_08(void)
{
    /* Eight logo writes succeed; the first dashboard write fails. */
    spy.fail_at = 9U;
    display_process(UINT32_MAX, &readings);
    display_process(fake_now_ms + LOGO_DISPLAY_MS, &readings);

    TEST_ASSERT_EQUAL_INT(9, spy.calls);
    TEST_ASSERT_EQUAL_INT(0, spy.pages[8]);
    TEST_ASSERT_EQUAL_STRING("FAULT OLED dashboard write\r\n", spy.last_log);
    display_process(fake_now_ms + LOGO_DISPLAY_MS + 1U, &readings);
    TEST_ASSERT_EQUAL_INT(9, spy.calls);
}

void test_display_process_09(void)
{
    enter_dashboard();
    TEST_ASSERT_EQUAL_INT(9, spy.calls);

    for (uint8_t page = 1U; page < 8U; page++)
    {
        display_process(fake_now_ms + LOGO_DISPLAY_MS, &readings);
        TEST_ASSERT_EQUAL_INT(page + 9U, spy.calls);
        TEST_ASSERT_EQUAL_INT(page, spy.pages[page + 8U]);
    }

    /* Page eight is the idle sentinel until a refresh is due. */
    display_process(fake_now_ms + LOGO_DISPLAY_MS, &readings);
    TEST_ASSERT_EQUAL_INT(16, spy.calls);
}

void test_display_process_10(void)
{
    enter_dashboard();
    TEST_ASSERT_EQUAL_INT(9, spy.calls);

    /* A null snapshot returns before advancing or transferring a page. */
    display_process(fake_now_ms + LOGO_DISPLAY_MS + 1U, NULL);

    TEST_ASSERT_EQUAL_INT(9, spy.calls);
    TEST_ASSERT_FALSE(display_is_splash());
}

void test_display_process_11(void)
{
    enter_dashboard();
    for (uint8_t page = 1U; page < 8U; page++)
    {
        display_process(fake_now_ms + LOGO_DISPLAY_MS, &readings);
    }
    TEST_ASSERT_EQUAL_INT(16, spy.calls);

    /* The elapsed interval is necessarily beyond the refresh interval for
       this maximum timestamp; refresh restarts transfers at page zero. */
    display_process(UINT32_MAX, &readings);

    TEST_ASSERT_EQUAL_INT(17, spy.calls);
    TEST_ASSERT_EQUAL_INT(0, spy.pages[16]);
}
